//! Firmware parity of the master IIR (4 sections, PM `0x945F2..0x94605`): the test-only ext40
//! reference against golden vectors, and the fast f32 path against the reference.
//!
//! The vectors are derived values only, generated by `python tools/fx_biquad_check.py
//! --golden-master` from the exact-arithmetic model that matches the oracle's run of `0x120FDB`
//! word for word (`docs/research/fx-dsp-map.md` section 6). The coefficients are firmware words;
//! the cascade structure (four sections in memory order, memory-word stores between sections)
//! is ASSUMED to be the one of the inline master IIR, which the oracle was not run on.

use super::biquad::ext40_ref;
use super::fw_coeffs::master_iir_sets;
use super::master_iir::MasterIir;

const BLOCKS: usize = 8;
const FRAMES: usize = 4;

const MASTER_GOLDEN_LEFT: [u32; 32] = [
    0xbc41a283, 0xbd346070, 0xbda2107c, 0xbd82000f, 0x3d0353b7, 0x3e068b57,
    0x3dd583c4, 0xbd8c79a7, 0xbe5e001b, 0xbe28ce2c, 0x3d3a2cd2, 0x3e557560,
    0x3e4640c7, 0x3d7fc886, 0xbd82cd9e, 0xbdeefbac, 0xbd90bc6d, 0x3ce53786,
    0x3d4ef148, 0xbdbe8949, 0xbe8b1357, 0xbe83055f, 0xbd008d10, 0x3e2911d8,
    0x3e166374, 0xbc3e191f, 0xbe105c73, 0xbe315fed, 0xbdf76740, 0xba31e941,
    0x3e0f321d, 0x3e4245bf,
];
const MASTER_GOLDEN_RIGHT: [u32; 32] = [
    0xbc78f582, 0xbd5b662a, 0xbd8f3d68, 0x3c808a91, 0x3e455c15, 0x3e980e92,
    0x3e325a20, 0xbdd749ca, 0xbea0e4ea, 0xbea853f3, 0xbe54dd97, 0xbcf41a48,
    0x3e27a043, 0x3e86ceaa, 0x3e0b21c4, 0xbe21af42, 0xbeaeb6f8, 0xbe63acc7,
    0x3db407a8, 0x3ea64c6f, 0x3eaa46db, 0x3e173a16, 0xbdb40595, 0xbe7e28c8,
    0xbe9057bd, 0xbe4a53e9, 0xbc5a8656, 0x3e540a14, 0x3e9d76d9, 0x3e249eb6,
    0xbe0cc20e, 0xbeaef09f,
];
const MASTER_GOLDEN_STATES: [u32; 16] = [
    0xbe20704c, 0xbe813a6f, 0xbdbc73b8, 0xbc9cc33c, 0xbe0f8e26, 0xbdee7867,
    0xbdb4cec2, 0xbda2c925, 0x396a092e, 0xbe85a7ed, 0xbd4f3628, 0xbd82d210,
    0x3ddfbcf5, 0xbe86386f, 0x3d1cdc69, 0xbddb5158,
];

/// Golden input, channel `ch` (0 left, 1 right), sample `n`; exact in f32.
fn input(ch: usize, n: usize) -> f32 {
    let (mul, add, modulus) = if ch == 0 { (37, 11, 64) } else { (53, 5, 61) };
    ((mul * n + add) % modulus) as f32 / 64.0 - 0.5
}

fn run_reference(ch: usize) -> (Vec<f32>, [[f32; 2]; 4]) {
    let sets = master_iir_sets();
    let mut st = [[0.0f32; 2]; 4];
    let mut out: Vec<f32> = (0..BLOCKS * FRAMES).map(|n| input(ch, n)).collect();
    let (blocks, rest) = out.as_chunks_mut::<FRAMES>();
    assert!(rest.is_empty());
    for block in blocks {
        for (s, c) in st.iter_mut().zip(&sets) {
            ext40_ref::stage(block, c, s);
        }
    }
    (out, st)
}

fn words(v: &[f32]) -> Vec<u32> {
    v.iter().map(|x| x.to_bits()).collect()
}

#[test]
fn ext40_reference_matches_the_master_iir_golden_vectors() {
    let (left, st_l) = run_reference(0);
    let (right, st_r) = run_reference(1);
    assert_eq!(words(&left), MASTER_GOLDEN_LEFT, "left output words");
    assert_eq!(words(&right), MASTER_GOLDEN_RIGHT, "right output words");
    for k in 0..4 {
        let got = [st_l[k][0], st_r[k][0], st_l[k][1], st_r[k][1]];
        assert_eq!(
            words(&got),
            MASTER_GOLDEN_STATES[4 * k..4 * k + 4],
            "section {k} state"
        );
    }
}

#[test]
fn fast_f32_master_iir_tracks_the_reference() {
    let (want, _) = run_reference(0);
    let mut iir = MasterIir::new();
    let got: Vec<f32> = (0..BLOCKS * FRAMES)
        .map(|n| iir.process_frame([input(0, n), input(1, n)])[0])
        .collect();
    let err = want
        .iter()
        .zip(&got)
        .map(|(&w, &g)| (w - g).abs())
        .fold(0.0f32, f32::max);
    assert!(err < 1e-5, "max abs error {err}");
}
